  .rec-card .data-point {
    font-size: 12px;
    color: var(--gray-500);
    margin-top: 6px;
    font-style: italic;
  }
  .sentiment-bar {
    display: flex;
    align-items: center;
    margin: 6px 0;
  }
  .sentiment-bar .label { width: 100px; font-size: 13px; color: var(--gray-700); }
  .sentiment-bar .bar-wrap {
    flex: 1;
    background: var(--gray-100);
    border-radius: 4px;
    height: 22px;
    overflow: hidden;
    margin: 0 10px;
  }
  .sentiment-bar .bar {
    height: 100%;
    border-radius: 4px;
    display: flex;
    align-items: center;
    padding-left: 8px;
    font-size: 11px;
    color: white;
    font-weight: 600;
  }
  .bar-pos { background: var(--success); }
  .bar-neg { background: var(--danger); }
  .sentiment-bar .count { width: 60px; text-align: right; font-size: 13px; color: var(--gray-500); }
  .correlation-meter {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 10px 0;
  }
  .corr-track {
    flex: 1;
    height: 8px;
    background: var(--gray-200);
    border-radius: 4px;
    position: relative;
  }
  .corr-needle {
    position: absolute;
    top: -4px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent);
    border: 2px solid white;
