  }
  .corr-labels { display: flex; justify-content: space-between; font-size: 11px; color: var(--gray-500); }
  footer {
    padding: 24px 0;
    text-align: center;
    color: var(--gray-300);
    font-size: 12px;
    border-top: 1px solid var(--gray-200);
    margin-top: 40px;
  }
</style>
</head>
